'use strict'

const { dependencyUpdatesFor, rangeSatisfiesTarget, targetMinNode, engineNodeMeetsMin } = require('../constants')
const { parsePomXml, getPomPropertyValue } = require('../util/pom')

function buildProposal(ctx, cds) {
  const updates = []
  const removals = []
  const dep = dependencyUpdatesFor(ctx.target)
  const minNode = targetMinNode(ctx.target)

  // Removals: @sap/cds-compiler always; @sap/cds-dk only in Node-only projects.
  // These deps own their own prompt (see runRemovals) — skip them here so
  // they are not double-proposed as regular updates.
  const removalNames = new Set(['@sap/cds-compiler'])
  if (!ctx.project.isJava) removalNames.add('@sap/cds-dk')

  if (ctx.project.isNode) {
    for (const pkgPath of ctx.project.packageJsonFiles) {
      let pkg
      try { pkg = JSON.parse(cds.utils.fs.readFileSync(pkgPath, 'utf8')) } catch { continue }

      for (const [name, targetRange] of Object.entries(dep.node)) {
        if (removalNames.has(name)) continue
        for (const kind of ['dependencies', 'devDependencies']) {
          const current = pkg[kind]?.[name]
          if (!current) continue
          if (rangeSatisfiesTarget(current, ctx.target)) continue
          if (current === targetRange) continue
          updates.push({
            file: pkgPath, name, from: current, to: targetRange,
            kind: kind === 'dependencies' ? 'node-dep' : 'node-devDep',
          })
        }
      }

      // engines.node: propose a bump only when the package actually declares
      // an `engines` block. Missing engines is a user choice, not a defect.
      if (minNode !== null && pkg.engines && Object.keys(pkg.engines).length > 0) {
        const current = pkg.engines.node
        if (!engineNodeMeetsMin(current, minNode)) {
          const to = `>=${minNode}`
          if (current !== to) {
            updates.push({
              file: pkgPath, name: 'engines.node', from: current || '(missing)', to,
              kind: 'node-engines-node',
            })
          }
        }
      }

      for (const name of removalNames) {
        for (const kind of ['dependencies', 'devDependencies']) {
          if (pkg[kind]?.[name]) {
            removals.push({
              file: pkgPath, name, from: pkg[kind][name], to: null,
              kind: kind === 'dependencies' ? 'node-dep' : 'node-devDep',
            })
          }
        }
      }
    }
  }

  if (ctx.project.isJava) {
    for (const pomPath of ctx.project.pomXmlFiles) {
      let pom
      try { pom = parsePomXml(pomPath) } catch { continue }
      for (const [name, value] of Object.entries(dep.java)) {
        const current = getPomPropertyValue(pom, name)
        if (current && current !== value) {
          updates.push({ file: pomPath, name, from: current, to: value, kind: 'pom-property' })
        }
      }
    }
  }

  return { updates, removals }
}

async function runRewrite(ctx, cds) {
  const { askYesNo, NonTTYError } = require('../util/prompt');
  const path = require('node:path');
  const { info, bold, dim } = require('../../../lib/util/term');

  const { updates, removals } = buildProposal(ctx, cds);
  ctx.proposal = { updates, removals };

  if (updates.length === 0) return { applied: false, aborted: false };

  console.log();
  console.log('These dependencies can be upgraded:');
  console.log();
  const byFile = new Map();
  for (const u of updates) {
    if (!byFile.has(u.file)) byFile.set(u.file, []);
    byFile.get(u.file).push(u);
  }
  for (const [file, list] of byFile) {
    console.log(`  ${bold(path.relative(cds.root, file))}`);
    const nameCol = Math.max(...list.map(u => u.name.length));
    const fromCol = Math.max(...list.map(u => u.from.length));
    for (const u of list) {
      console.log(`    ${u.name.padEnd(nameCol)}: ${u.from.padEnd(fromCol)} → ${u.to}`);
    }
  }
  console.log();

  let accept;
  try {
    accept = await askYesNo('Update the dependencies?');
  } catch (e) {
    if (e instanceof NonTTYError) {
      console.log('Non-interactive mode: stopping without changes. Re-run in a terminal to apply.');
      return { applied: false, aborted: true, reason: 'non-tty' };
    }
    throw e;
  }
  if (!accept) return { applied: false, aborted: true, reason: 'user-declined' };

  // Apply.
  let anyWritten = false;
  const nodeUpdates = updates.filter(u =>
    u.kind === 'node-dep' || u.kind === 'node-devDep' || u.kind === 'node-engines-node');
  const pomUpdates = updates.filter(u => u.kind === 'pom-property');

  const nodeFiles = new Set(nodeUpdates.map(u => u.file));
  for (const pkgPath of nodeFiles) {
    const pkg = JSON.parse(cds.utils.fs.readFileSync(pkgPath, 'utf8'));
    let count = 0;
    for (const u of nodeUpdates.filter(x => x.file === pkgPath)) {
      if (u.kind === 'node-engines-node') {
        pkg.engines = pkg.engines || {};
        pkg.engines.node = u.to;
        count++;
        continue;
      }
      const k = u.kind === 'node-dep' ? 'dependencies' : 'devDependencies';
      if (pkg[k]?.[u.name]) { pkg[k][u.name] = u.to; count++; }
    }
    if (count > 0) {
      cds.utils.fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
      console.log(`  ${info('✓')} ${path.relative(cds.root, pkgPath)}  ${dim(`(${count} changes)`)}`);
      anyWritten = true;
    }
  }

  if (pomUpdates.length > 0) {
    const { updatePomPropertyInFile } = require('../util/pom');
    const pomFiles = new Set(pomUpdates.map(u => u.file));
    for (const pomPath of pomFiles) {
      let count = 0;
      for (const u of pomUpdates.filter(x => x.file === pomPath)) {
        if (updatePomPropertyInFile(pomPath, u.name, u.to)) count++;
      }
      if (count > 0) {
        console.log(`  ${info('✓')} ${path.relative(cds.root, pomPath)}  ${dim(`(${count} changes)`)}`);
        anyWritten = true;
      }
    }
  }

  ctx.rewriteRan = anyWritten;
  return { applied: anyWritten, aborted: false };
}

module.exports = { runRewrite, buildProposal }
